mapper.update:
UPDATE t_chat_message_outbox
SET event_status = 1,
    sent_time = #{sentTime}
WHERE event_id = #{eventId}
  AND event_status IN (0, 2)

UPDATE t_chat_message_outbox
SET event_status = 2,
    retry_count = retry_count + 1,
    next_retry_time = #{nextRetryTime}
WHERE event_id = #{eventId}
  AND event_status IN (0, 2)

mapper.select:
SELECT *
FROM t_chat_message_outbox
WHERE sender_id = #{senderId}
AND client_message_id = #{clientMessageId}
LIMIT 1
